  useEffect(() => {
    if (level > previousLevelRef.current) {
      setCelebrationLevel(level);
      const timeout = window.setTimeout(() => setCelebrationLevel(null), 3000);
      previousLevelRef.current = level;
      return () => window.clearTimeout(timeout);
