import { describe, expect, it, vi } from 'vitest';
import { QuestCard } from './quest-card.component';
import type { Quest } from '@domain/model/quest.model';

const QUEST: Quest = {
  id: 'q_1',
  title: 'Enfrentar o dragão',
  description: 'Derrote a besta',
  status: 'open',
  difficulty: 'normal',
  xpReward: 25,
  createdAt: '2026-01-01T00:00:00.000Z',
};

describe('debug remove', () => {
  it('clicks remove', async () => {
    const user = userEvent.setup();
    const onRemove = vi.fn();
    const confirmSpy = vi.spyOn(window, 'confirm').mockReturnValue(true);
    render(<QuestCard quest={QUEST} columnStatus="open" onAdvance={vi.fn()} onEdit={vi.fn()} onRemove={onRemove} />);
    await user.click(screen.getByRole('button', { name: 'Remover' }));
    console.log('confirm calls', confirmSpy.mock.calls.length);
    console.log('onRemove calls', onRemove.mock.calls.length);
    expect(onRemove).toHaveBeenCalled();
    confirmSpy.mockRestore();
  });
});
