    ['easy', 10],
    ['normal', 25],
    ['high', 50],
  ];

  it.each(cases)('should reward a %s quest with %d XP', (difficulty, xpReward) => {
    expect(withXpReward({ ...quest, difficulty })).toEqual({ ...quest, difficulty, xpReward });
  });
});
