import type { Tag } from './tag.model';

export type QuestStatus = 'open' | 'in_progress' | 'resolved';
export const QUEST_DIFFICULTIES = ['easy', 'normal', 'high'] as const;
export type QuestDifficulty = (typeof QUEST_DIFFICULTIES)[number];

