  title: string;
  description: string;
  difficulty: QuestDifficulty;
  dueDate?: string | null;
  tagIds?: string[];
}

export interface QuestUpdateInput {
  title?: string;
  description?: string;
  difficulty?: QuestDifficulty;
  status?: QuestStatus;
  dueDate?: string | null;
  tagIds?: string[];
}

export interface PageInfo {
  limit: number;
  offset: number;
