  limit: z.number(),
  offset: z.number(),
  hasNextPage: z.boolean(),
  hasPreviousPage: z.boolean(),
}) satisfies ZodType<PageInfo>;

export const paginatedQuestSchema = z.object({
  nodes: z.array(questSchema),
  count: z.number(),
  pageInfo: pageInfoSchema,
}) satisfies ZodType<Paginated<Quest>>;

