import type { Tag } from './tag.model';

export type QuestStatus = 'open' | 'in_progress' | 'resolved';
export const QUEST_DIFFICULTIES = ['easy', 'normal', 'high'] as const;
export type QuestDifficulty = (typeof QUEST_DIFFICULTIES)[number];

export interface Quest {
  id: string;
  title: string;
  description: string;
  status: QuestStatus;
  difficulty: QuestDifficulty;
  xpReward: number;
  dueDate: string | null;
  tags: Tag[];
  createdAt: string;
}

export interface QuestInput {
  title: string;
  description: string;
  difficulty: QuestDifficulty;
  dueDate?: string | null;
  tagIds?: string[];
}

export interface QuestUpdateInput {
  title?: string;
  description?: string;
  difficulty?: QuestDifficulty;
  status?: QuestStatus;
  dueDate?: string | null;
  tagIds?: string[];
}

export interface PageInfo {
  limit: number;
  offset: number;
  hasNextPage: boolean;
  hasPreviousPage: boolean;
}

export interface Paginated<T> {
  nodes: T[];
  count: number;
  pageInfo: PageInfo;
}
import { QUEST_DIFFICULTIES, type Paginated, type PageInfo, type Quest } from '@domain/model/quest.model';
import { tagSchema } from '@data/tags/tag.schema';
import { type ZodType, z } from 'zod';

export const questStatusSchema = z.enum(['open', 'in_progress', 'resolved']);
export const questDifficultySchema = z.enum(QUEST_DIFFICULTIES);

export const questSchema = z.object({
  id: z.string(),
  title: z.string(),
  description: z.string(),
  status: questStatusSchema,
  difficulty: questDifficultySchema,
  xpReward: z.number(),
  dueDate: z.iso.date().nullable(),
  tags: z.array(tagSchema),
  createdAt: z.string(),
}) satisfies ZodType<Quest>;

const pageInfoSchema = z.object({
  limit: z.number(),
  offset: z.number(),
  hasNextPage: z.boolean(),
  hasPreviousPage: z.boolean(),
}) satisfies ZodType<PageInfo>;

export const paginatedQuestSchema = z.object({
  nodes: z.array(questSchema),
  count: z.number(),
  pageInfo: pageInfoSchema,
}) satisfies ZodType<Paginated<Quest>>;

